package com.github.t24ph.codeassistant.assistant;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

import com.github.t24ph.codeassistant.assistant.strategy.Strategy;
import com.github.t24ph.codeassistant.assistant.strategy.StrategyFactory;

public class Assistant {
    private final Strategy strategy;

    public Assistant(Strategy strategy) {
        this.strategy = strategy;
    }

    public String process(String input) {
        return strategy.process(input);
    }

    public static Assistant create(String input) {
        List<Strategy> strategies = new ArrayList<>();
        List<String> words = Arrays.asList(input.split(" "));
        for (String word : words) {
            Matcher matcher = Pattern.compile("\\|\\|").matcher(word);
            if (matcher.find()) {
                strategies.add(StrategyFactory.create(word));
            } else {
                strategies.add(StrategyFactory.create(word, "system"));
            }
        }
        return new Assistant(new StrategyChain(strategies));
    }
}
