package com.github.t24ph.codeassistant.assistant.strategy;

public class StrategyFactory {
    public static Strategy create(String input, String type) {
        if (input.startsWith("|") && input.endsWith("|")) {
            return new UserStrategy(input.substring(1, input.length() - 1));
        } else if (input.startsWith("<|") && input.endsWith("|>")) {
            return new SystemStrategy(input.substring(2, input.length() - 2));
        } else if (input.startsWith("<") && input.endsWith(">")) {
            return new AssistantStrategy(input.substring(1, input.length() - 1));
        } else {
            return new DefaultStrategy(input, type);
        }
    }
}
