public class HttpRequest {
    private final URL url;
    private final URLConnection connection;
    private final Map<String, String> headers;
    private final String method;

    public HttpRequest(URL url, String method) {
        this.url = url;
        this.connection = url.openConnection();
        this.headers = new HashMap<String, String>();
        this.method = method;
    }

    public HttpRequest header(String name, String value) {
        headers.put(name, value);
        return this;
    }

    public HttpRequest header(String name, int value) {
        headers.put(name, Integer.toString(value));
        return this;
    }

    public HttpRequest header(String name, long value) {
        headers.put(name, Long.toString(value));
        return this;
    }

    public HttpRequest header(String name, double value) {
        headers.put(name, Double.toString(value));
        return this;
    }

    public HttpRequest header(String name, boolean value) {
        headers.put(name, Boolean.toString(value));
        return this;
    }

    public HttpRequest header(String name, Object value) {
        headers.put(name, value.toString());
        return this;
    }

    public HttpRequest connect() throws IOException {
        connection.setDoOutput(true);
        connection.setDoInput(true);
        connection.setUseCaches(false);
        connection.setRequestMethod(method);
        connection.setRequestProperty("Content-Type", "application/x-www-form-urlencoded");
        for (Map.Entry<String, String> entry : headers.entrySet()) {
            connection.setRequestProperty(entry.getKey(), entry.getValue());
        }
        return this;
    }

    public int code() throws IOException {
        return ((HttpURLConnection) connection).getResponseCode();
