package fi.csc.puhelinluettelo.gui;

import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;

import fi.csc.puhelinluettelo.domain.Contact;

public class ContactList {

	private final List<Contact> contacts = new ArrayList<>();

	public void addContact(Contact contact) {
		contacts.add(contact);
	}

	public void removeContact(Contact contact) {
		contacts.remove(contact);
	}

	public List<Contact> getContacts() {
		return contacts;
	}

	public List<Contact> getContactsByName(String name) {
		return contacts.stream().filter(c -> c.getName().toLowerCase().contains(name.toLowerCase()))
				.collect(Collectors.toList());
	}

	public List<Contact> getContactsByPhoneNumber(String phoneNumber) {
		return contacts.stream().filter(c -> c.getPhoneNumber().contains(phoneNumber))
				.collect(Collectors.toList());
	}
}
