package com.github.ajsbyte.codewars.kata.6kyu;

import java.util.Arrays;

public class FindTheParityOutlier {
    public static int findOutlier(int[] array) {
        int even = 0, odd = 0;
        for (int i : array) {
            if (i % 2 == 0)
                even++;
            else
                odd++;
        }
        return even > odd? Arrays.stream(array).filter(i -> i % 2!= 0).findFirst().getAsInt() : Arrays.stream(array).filter(i -> i % 2 == 0).findFirst().getAsInt();
    }
}
