public class TheSupermarketQueue {
    public static int queueTime(int[] customers, int n) {
        int[] queue = new int[n];
        int time = 0;
        for (int customer : customers) {
            int index = 0;
            int min = 0;
            for (int i = 0; i < n; i++) {
                if (queue[i] < queue[min]) {
                    min = i;
                }
            }
            queue[min] += customer;
            time = Math.max(time, queue[min]);
        }
        return time;
    }
