import br.com.caelum.vraptor.example.dao.UserDao;
import br.com.caelum.vraptor.example.model.User;
import br.com.caelum.vraptor.validator.Validator;

@Controller
public class ClassX {

	private final Result result;
	private final UserDao dao;
	private final Validator validator;

	@Inject
	public ClassX(Result result, UserDao dao, Validator validator) {
		this.result = result;
		this.dao = dao;
		this.validator = validator;
	}

	@Get
	@Path("/users")
	public void list() {
		List<User> users = dao.list();
		result.include("users", users);
	}

	@Post
	@Path("/users")
	public void save(User user) {
		validator.validate(user);
		validator.onErrorUsePageOf(ClassY.class).list();
		dao.save(user);
		result.redirectTo(ClassX.class).list();
	}
}
