package br.com.caelum.vraptor.processor.processor;

import java.io.File;
import java.io.IOException;
import java.util.List;

import br.com.caelum.vraptor.processor.annotation.ProcessorAnnotation;
import br.com.caelum.vraptor.processor.exception.ProcessorException;
import br.com.caelum.vraptor.processor.processor.annotation.ProcessorAnnotationImpl;

public class Processor {

	private ProcessorAnnotation processorAnnotation;

	public Processor(ProcessorAnnotation processorAnnotation) {
		this.processorAnnotation = processorAnnotation;
	}

	public void process(String path, String outputPath) throws ProcessorException, IOException {
		List<File> files = processorAnnotation.getFiles(path);
		for (File file : files) {
			if (processorAnnotation.getProcessor().isProcessable(file)) {
				processorAnnotation.getProcessor().process(file, outputPath);
			}
		}
	}

	public void process(String path, String outputPath, String include) throws ProcessorException, IOException {
		List<File> files = processorAnnotation.getFiles(path);
		for (File file : files) {
			if (processorAnnotation.getProcessor().isProcessable(file)) {
				if (processorAnnotation.getProcessor().match(file, include)) {
					processorAnnotation.getProcessor().process(file, outputPath);
				}
			}
		}
	}

	public void process(String path, String outputPath, String exclude) throws ProcessorException, IOException {
		List<File> files = processorAnnotation.getFiles(path);
		for (File file : files) {
			if (processorAnnotation.getProcessor().isProcessable(file)) {
				if (!processorAnnotation.getProcessor().match(file, exclude)) {
					processorAnnotation.getProcessor().process(file, outputPath);
				}
			}
		}
	}

