package be.ucll.stud.security.web.controllers;

import be.ucll.stud.security.web.models.dto.LoginDTO;
import be.ucll.stud.security.web.models.dto.RegisterDTO;
import be.ucll.stud.security.web.models.dto.UserDTO;
import be.ucll.stud.security.web.services.AuthService;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

import java.util.List;

@RestController
@RequestMapping("/api/auth")
public class AuthController {

    @Autowired
    private AuthService authService;

    @PostMapping("/register")
    public ResponseEntity<String> register(@RequestBody RegisterDTO registerDTO) {
        authService.register(registerDTO);
        return new ResponseEntity<>("User created", HttpStatus.CREATED);
    }

    @PostMapping("/login")
    public ResponseEntity<UserDTO> login(@RequestBody LoginDTO loginDTO) {
        UserDTO userDTO = authService.login(loginDTO);
        return new ResponseEntity<>(userDTO, HttpStatus.OK);
    }

    @GetMapping("/users")
    public ResponseEntity<List<UserDTO>> getUsers() {
        List<UserDTO> userDTOList = authService.getUsers();
        return new ResponseEntity<>(userDTOList, HttpStatus.OK);
    }
}
