package hu.bme.mit.train.railway;

import hu.bme.mit.train.TrainCar;
import hu.bme.mit.train.TrainController;
import hu.bme.mit.train.TrainData;
import hu.bme.mit.train.TrainStation;

public class RailwayStation extends TrainStation {

    public RailwayStation(TrainController controller, TrainData data) {
        super(controller, data);
    }

    @Override
    public void update() {
        int carId = 0;
        for (TrainCar car : cars) {
            if (car.getDestination() == null) {
                carId = car.getId();
                break;
            }
        }
        if (carId!= 0) {
            TrainCar car = cars.get(carId);
            if (car.getDestination()!= null) {
                if (car.getDestination().equals(destination)) {
                    car.setDestination(null);
                    destination = null;
                }
            } else {
                car.setDestination(destination);
                destination = null;
            }
        }
    }
}
