package com.github.kostasko.oauth2.server.handler;

import com.github.kostasko.oauth2.server.exception.InvalidTokenException;
import com.github.kostasko.oauth2.server.model.Token;
import com.github.kostasko.oauth2.server.service.TokenService;
import io.vertx.core.json.JsonObject;
import io.vertx.ext.web.RoutingContext;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class TokenHandler {

    private static final Logger log = LoggerFactory.getLogger(TokenHandler.class);

    private final TokenService tokenService;

    public TokenHandler(TokenService tokenService) {
        this.tokenService = tokenService;
    }

    public void handle(RoutingContext routingContext) {
        log.info("Handling token request");
        String tokenParam = routingContext.request().getParam("token");

        if (tokenParam == null) {
            log.error("Token request without token parameter");
            routingContext.fail(400);
            return;
        }

        Token token;
        try {
            token = tokenService.getToken(tokenParam);
        } catch (InvalidTokenException e) {
            log.error("Invalid token", e);
            routingContext.fail(401);
            return;
        }

        JsonObject result = new JsonObject();
        result.put("token", token.getToken());
        result.put("user", token.getUser());
        result.put("algorithm", token.getAlgorithm());
        result.put("expires", token.getExpires());

        routingContext.response().putHeader("Content-Type", "application/json");
        routingContext.response().end(result.encodePrettily());
    }
}
