from collections import defaultdict

def main():
    while True:
        n = int(sys.stdin.readline().strip())
        if n == 0:
            break
        m = int(sys.stdin.readline().strip())
        graph = defaultdict(list)
        for _ in range(n):
            u, v = map(int, sys.stdin.readline().strip().split())
            graph[u].append(v)
        for _ in range(m):
            u, v = map(int, sys.stdin.readline().strip().split())
            graph[u].append(v)
        print(bfs(graph))

def bfs(graph):
    visited = [False] * len(graph)
    queue = [0]
    while queue:
        u = queue.pop(0)
        if not visited[u]:
            visited[u] = True
            for v in graph[u]:
                queue.append(v)
    return sum(visited)

if __name__ == '__main__':
    main()
