    /**
     * Извлича zip архив в указаната дестинация след проверка на пътищата на членовете.
     * 
     * Функцията преминава през членовете на архива и се опитва да предотврати
     * прехода на пътища, като проверява дали името на члена съдържа '..'.
     */
    public static void main(String[] args) {
        ClassX.unzip(args[0], args[1]);
    }

    public static void unzip(String zipFile, String destDir) {
        File destDirFile = new File(destDir);
        if (!destDirFile.exists()) {
            destDirFile.mkdirs();
        }

        try {
            ZipInputStream zipIn = new ZipInputStream(new FileInputStream(zipFile));
            ZipEntry entry = zipIn.getNextEntry();

            while (entry!= null) {
                String filePath = destDir + File.separator + entry.getName();
                if (!entry.isDirectory()) {
                    File newFile = new File(filePath);
                    newFile.getParentFile().mkdirs();
                    newFile.createNewFile();
                    FileOutputStream fos = new FileOutputStream(newFile);
                    byte[] buffer = new byte[1024];
                    int len;
                    while ((len = zipIn.read(buffer)) > 0) {
                        fos.write(buffer, 0, len);
                    }
                    fos.close();
                } else {
                    File newDir = new File(filePath);
                    newDir.mkdirs();
                }
                zipIn.closeEntry();
                entry = zipIn.getNextEntry();
            }
            zipIn.close();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}

