/**
 * Represents a variable declaration.
 * 
 * @author 
 * @since 2.0
 */
public class VariableDeclarationExpr extends Expression implements Visitable {

    private final Type type;
    private final String name;
    private final Expression value;

    /**
     * Creates a new variable declaration.
     * 
     * @param type The type of the variable.
     * @param name The name of the variable.
     * @param value The value of the variable.
     */
    public VariableDeclarationExpr(Type type, String name, Expression value) {
        this.type = type;
        this.name = name;
        this.value = value;
    }

    public Type getType() {
        return type;
    }

    public String getName() {
        return name;
    }

    public Expression getValue() {
        return value;
    }

    @Override
    public <R, A> R accept(VoidVisitor<R, A> visitor, A arg) {
        return visitor.visit(this, arg);
    }

    @Override
    public String toString() {
        return type + " " + name + " = " + value;
    }

    @Override
    public Node clone() {
        return new VariableDeclarationExpr(type, name, value);
    }
}
