package com.github.michaelruocco.codewars.kyu6;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;

public class CountingDuplicates {

    @Test
    public void test() {
        assertEquals(2, countDuplicates("aabbcde"));
        assertEquals(0, countDuplicates("Indivisibilities"));
        assertEquals(2, countDuplicates("aA11"));
        assertEquals(2, countDuplicates("abcde"));
        assertEquals(0, countDuplicates("abcdeaa"));
        assertEquals(2, countDuplicates("abcdeaB"));
        assertEquals(2, countDuplicates("Indivisibilities"));
        assertEquals(2, countDuplicates("a"));
        assertEquals(0, countDuplicates("aA1"));
        assertEquals(0, countDuplicates(""));
        assertEquals(0, countDuplicates("is"));
    }

    public static int countDuplicates(String s) {
        if (s == null || s.isEmpty()) {
            return 0;
        }

        int[] count = new int[26];
        for (char c : s.toCharArray()) {
            count[c - 'a']++;
        }

        int duplicates = 0;
        for (int i = 0; i < count.length; i++) {
            if (count[i] > 1) {
                duplicates++;
            }
        }

        return duplicates;
    }
}
