package com.github.hcsp.classloader;

import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import java.lang.reflect.InvocationTargetException;
import java.lang.reflect.Method;
import java.net.MalformedURLException;
import java.net.URL;
import java.net.URLClassLoader;

public class MyClassLoader extends URLClassLoader {
    public MyClassLoader(URL[] urls) {
        super(urls);
    }

    @Override
    protected Class<?> findClass(String name) throws ClassNotFoundException {
        try {
            File classFile = new File(name.replace(".", "/") + ".class");
            if (!classFile.exists()) {
                throw new ClassNotFoundException("No such class: " + name);
            }
            byte[] classData = new byte[(int) classFile.length()];
            FileInputStream in = new FileInputStream(classFile);
            in.read(classData);
            in.close();
            return defineClass(name, classData, 0, classData.length);
        } catch (IOException e) {
            throw new ClassNotFoundException("No such class: " + name);
        }
    }

    public static void main(String[] args) throws ClassNotFoundException, NoSuchMethodException, InvocationTargetException, IllegalAccessException {
        // 启动类加载器
        URL[] urls = {new URL("file:./target/classes/")};
        URLClassLoader classLoader = new URLClassLoader(urls);

        // 加载 MyClassLoader 并获取它的构造方法
        Class<?> myClassLoaderClazz = classLoader.loadClass("com.github.hcsp.classloader.MyClassLoader");
        Method constructor = myClassLoaderClazz.getDeclaredConstructor(URL[].class);
        constructor.setAccessible(true);

        // 构造一个新的 MyClassLoader
        MyClassLoader myClassLoader = (MyClassLoader) constructor.newInstance(new Object[]{urls});

        // 加载 Hello 类
        Class<?> helloClazz = myClassLoader.loadClass("com.github.hcsp.classloader.Hello");

        // 调用 Hello 的 greet() 方法
        Method greet = helloClazz.getDeclaredMethod("greet", String.class);
        greet.invoke(helloClazz.newInstance(), "World");
    }
}
