/**
 * The ExerciseType enumeration.
 */
public enum ExerciseType {

    EXERCISE("exercise"),
    PROJECT("project"),
    TEMPLATE("template"),
    TEXT("text");

    private static final Logger log = LoggerFactory.getLogger(ExerciseType.class);

    private final String exerciseType;

    ExerciseType(String exerciseType) {
        this.exerciseType = exerciseType;
    }

    public String getExerciseType() {
        return exerciseType;
    }

    /**
     * @param exerciseType
     * @return the exercise type
     */
    public static ExerciseType fromExerciseType(String exerciseType) {
        return Arrays.stream(ExerciseType.values()).filter(type -> type.exerciseType.equals(exerciseType)).findFirst().orElse(null);
    }

    public static ExerciseType fromString(String exerciseType) {
        return Arrays.stream(ExerciseType.values()).filter(type -> type.exerciseType.equals(exerciseType)).findFirst().orElse(null);
    }

    public static ExerciseType fromExerciseType(ExerciseType exerciseType) {
        return exerciseType;
    }

    public static ExerciseType fromExerciseType(String exerciseType, String defaultExerciseType) {
        if (exerciseType!= null) {
            return fromExerciseType(exerciseType);
        }
        log.warn("No exercise type found for exercise type {}, using default {}", exerciseType, defaultExerciseType);
        return fromExerciseType(defaultExerciseType);
    }
}
