 * <li>a.b.c</li>
 * <li>a.b.c.d</li>
 * </ul>
 * <p>
 * 这些名称可以是类，方法，变量，属性，构造函数，接口或枚举。
 */
public class SimpleNameExpr extends Expression {

    /**
     * 名称的字符串表示。
     */
    private String name;

    public SimpleNameExpr(String name) {
        this.name = name;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    @Override
    public Node clone() {
        SimpleNameExpr clone = new SimpleNameExpr(name);
        clone.setClone(this);
        return clone;
    }
}
