package com.github.misterpeabody.codewars.kata.kyu7;

import java.util.Arrays;

/**
 * Sum of Differences in an Array
 *
 * Description:
 * Given an array of integers, return the sum of the absolute differences between all pairs of numbers:
 *
 * sum(array) -> number
 *
 * For example, for [2, 1, 10], we have:
 *
 * 2 - 1 = 1
 * 2 - 10 = 8
 * 1 - 10 = 9
 * 1 + 8 + 9 = 18
 *
 * So sum(array) = 18
 *
 * For [1, 2, 3], sum(array) = 0
 */
public class SumOfDifferencesInArray {

    public static int sumOfDifferences(int[] arr) {
        int sum = 0;
        for (int i = 0; i < arr.length - 1; i++) {
            for (int j = i + 1; j < arr.length; j++) {
                int diff = Math.abs(arr[i] - arr[j]);
                sum += diff;
            }
        }
        return sum;
    }

    public static int sumOfDifferences2(int[] arr) {
        int sum = 0;
        for (int i = 0; i < arr.length; i++) {
            for (int j = i + 1; j < arr.length; j++) {
                sum += Math.abs(arr[i] - arr[j]);
            }
        }
        return sum;
    }

    public static void main(String[] args) {
        int[] arr = {2, 1, 10};
        int sum = sumOfDifferences(arr);
        System.out.println(sum);
        sum = sumOfDifferences2(arr);
        System.out.println(sum);
    }

}
