package test.java.com.github.sarxos.javafx.fxml;

import javafx.application.Application;
import javafx.fxml.FXMLLoader;
import javafx.scene.Scene;
import javafx.scene.layout.Pane;
import javafx.stage.Stage;
import org.junit.Test;

import java.io.IOException;

import static org.junit.Assert.assertNotNull;

/**
 * @author 
 */
public class TestFxml extends Application {

    private static final String FXML_FILE = "test/java/com/github/sarxos/javafx/fxml/TestFxml.fxml";

    @Test
    public void testFxml() throws IOException {
        FXMLLoader fxmlLoader = new FXMLLoader(getClass().getResource(FXML_FILE));
        Pane pane = fxmlLoader.load();
        assertNotNull(pane);
    }

    @Override
    public void start(Stage primaryStage) throws Exception {
        FXMLLoader fxmlLoader = new FXMLLoader(getClass().getResource(FXML_FILE));
        Pane pane = fxmlLoader.load();
        assertNotNull(pane);
        primaryStage.setScene(new Scene(pane));
        primaryStage.show();
    }

    public static void main(String[] args) {
        launch(args);
    }

}
