package com.github.bjoernh.codefights.challenges.easy;

import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;

import com.github.bjoernh.codefights.challenges.base.Challenge;
import com.github.bjoernh.codefights.challenges.base.ChallengeResult;
import com.github.bjoernh.codefights.challenges.base.ChallengeRunner;

/**
 * Challenge for CodeFights.
 *
 * @author 
 * @see <a href="https://codefights.com/challenge/e6k4i58C247i4T448">https://codefights.com/challenge/e6k4i58C247i4T448</a>
 */
public class CountingSheep implements Challenge {

    @Override
    public String getName() {
        return "Counting Sheep";
    }

    @Override
    public String getDescription() {
        return "Counting sheep in the zoo is not easy, but what is the problem with counting sheep in the zoo?";
    }

    @Override
    public ChallengeResult run(String input) {
        List<String> inputList = Arrays.asList(input.split(","));
        List<Integer> sheepCount = inputList.stream().map(Integer::valueOf).collect(Collectors.toList());
        int count = sheepCount.stream().filter(i -> i > 0).mapToInt(i -> i).sum();
        return new ChallengeResult(count, "The zoo has " + count + " sheep.");
    }

    @Override
    public ChallengeRunner getRunner() {
        return new ChallengeRunner(this);
    }

}
