package com.github.hcsp.io;

import java.io.File;
import java.io.FilenameFilter;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class FileSearch {
    // 找到第一个路径中包含text的.java文件
    public static List<JavaFile> search(String path, String text) {
        // 请实现这个方法，返回path路径中包含text字符串的Java文件列表
        File file = new File(path);
        String[] files = file.list(new FilenameFilter() {
            @Override
            public boolean accept(File dir, String name) {
                return name.endsWith(".java");
            }
        });
        List<JavaFile> result = new ArrayList<>();
        for (String file1 : files) {
            JavaFile javaFile = new JavaFile(file.getAbsolutePath() + "/" + file1);
            if (javaFile.contains(text)) {
                result.add(javaFile);
            }
        }
        return result;
    }

    public static void main(String[] args) {
        System.out.println(search("src/main/java", "System.out").toString());
    }

    // 一个Java文件，包含文件名和文件内容
    public static class JavaFile {
        String fileName;
        String content;

        public JavaFile(String fileName) {
            this.fileName = fileName;
            this.content = FileUtils.readFileContent(fileName);
        }

        public boolean contains(String text) {
            return content.contains(text);
        }

        @Override
        public String toString() {
            return "JavaFile{" + "fileName='" + fileName + '\'' + ", content='" + content + '\'' + '}';
        }
    }
