package it.unipi.dii.sdi.lab.mailcap;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.net.URL;
import java.util.ArrayList;
import java.util.List;

public class Mailcap {
    private List<MailcapEntry> entries;

    public Mailcap(URL url) throws IOException {
        entries = new ArrayList<MailcapEntry>();
        BufferedReader reader = new BufferedReader(new InputStreamReader(url.openStream()));
        String line;
        while ((line = reader.readLine())!= null) {
            if (!line.trim().isEmpty()) {
                entries.add(new MailcapEntry(line));
            }
        }
    }

    public String findMatch(String mimeType) {
        for (MailcapEntry entry : entries) {
            if (mimeType.equals(entry.getMimeType())) {
                return entry.getCommand();
            }
        }
        return null;
    }

    public static void main(String[] args) throws IOException {
        Mailcap mailcap = new Mailcap(new URL("http://www.freedesktop.org/standards/mime-info/mailcap"));
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String mimeType;
        while ((mimeType = reader.readLine())!= null) {
            String command = mailcap.findMatch(mimeType);
            if (command!= null) {
                System.out.println(command);
            } else {
                System.out.println("No command found for " + mimeType);
            }
        }
    }
}
