    String[] mime_types = mime_type.split(";");
    String[] filename_parts = filename.split(";");
    for (String mime_type_part : mime_types) {
        for (String filename_part : filename_parts) {
            String command = "file -b --mime-type \"" + filename_part + "\"";
            try {
                Process p = Runtime.getRuntime().exec(command);
                BufferedReader br = new BufferedReader(new InputStreamReader(p.getInputStream()));
                String line = br.readLine();
                if (line.equals(mime_type_part)) {
                    return command;
                }
            } catch (Exception e) {
                e.printStackTrace();
            }
        }
    }
    return "";
