private static String[] split(String s) {
    String[] splitted = s.split(",");
    for (int i = 0; i < splitted.length; i++) {
        splitted[i] = splitted[i].trim();
        if (splitted[i].contains("\"")) {
            int first = splitted[i].indexOf("\"");
            int last = splitted[i].indexOf("\"", first + 1);
            if (last!= -1) {
                String firstPart = splitted[i].substring(0, first);
                String lastPart = splitted[i].substring(last + 1);
                splitted[i] = firstPart + lastPart;
            }
        }
    }
    return splitted;
}

