/**
 * Challenge Description:
 * 
 * Pangrams are sentences constructed by using every letter of the alphabet at least once.
 * 
 * For example: the sentence "The quick brown fox jumps over the lazy dog" is a pangram, because it uses the letters A-Z at least once (case is irrelevant).
 * 
 * Write a program which determines whether a given sentence is a pangram. Ignore the case of the alphabet.
 * 
 * Input sample:
 * 
 * The first argument is a path to a file. Each line includes a test sentence. E.g.
 * 
 * "The quick brown fox jumps over the lazy dog"
 * "We promptly judged antique ivory buckles for the next prize"
 * 
 * Output sample:
 * 
 * Print out True if the sentence is a pangram, or False if not. E.g.
 * 
 * True
 * False
 * 
 * Constraints:
 * 
 * 0 < length of sentence <= 1000
 * 
 * @author 
 *
 */
public class Pangrams extends AbstractChallenge {

	public Pangrams() {
		super("moderate", "pangrams");
	}

	@Override
	protected void solve(BufferedReader reader) throws IOException {
		String line = reader.readLine();
		while (line!= null) {
			String[] words = line.split("\\s+");
			Set<Character> alphabet = new HashSet<>();
			for (String word : words) {
				alphabet.addAll(Arrays.asList(word.toLowerCase().toCharArray()));
			}
			System.out.println(alphabet.size() == 26);
			line = reader.readLine();
		}
	}

}
