 * Sum of positive</a>.
 * 
 * @author Rodion "rodde" Efremov
 * @version 1.6
 * @since 1.6
 */
public class SumOfPositive {
    /**
     * Computes the sum of all positive numbers in the given array.
     * 
     * @param numbers the given array.
     * @return the sum of all positive numbers in the given array.
     */
    public static int sum(int[] numbers) {
        return IntStream.of(numbers)
                       .filter(x -> x > 0)
                       .sum();
    }
}
