public class NiceArray {
	public static boolean isNice(int[] arr) {
		int sum = 0;
		for (int i = 0; i < arr.length; i++) {
			sum += arr[i];
		}

		for (int i = 0; i < arr.length; i++) {
			if (arr[i] > sum) {
				return false;
			}
		}

		return true;
	}
