package com.github.codetojoy.codingproblems.hard;

import java.util.Arrays;

/**
 * Given a list of numbers 1...n, where n is the length of the list.
 * 
 * Your task is to find the missing number.
 * 
 * Example:
 * 
 * Input: [1,2,3,4,5,6,8]
 * 
 * Output: 7
 * 
 * @author 
 */
public class FindTheMissingNumber {

    public static void main(String[] args) {
        int[] input = { 1, 2, 3, 4, 5, 6, 8 };
        System.out.println(find(input));
    }

    private static int find(int[] input) {
        int sum = Arrays.stream(input).sum();
        int expectedSum = (input.length + 1) * (input.length / 2);
        return expectedSum - sum;
    }
}
