public class Sudoku {

    private final int[][] board;

    public Sudoku(int[][] board) {
        this.board = board;
    }

    public Set<Integer> getPossibleNumbers(int row, int col) {
        Set<Integer> possibleNumbers = new HashSet<>();
        possibleNumbers.addAll(getPossibleNumbersForRow(row));
        possibleNumbers.addAll(getPossibleNumbersForCol(col));
        possibleNumbers.addAll(getPossibleNumbersForBox(row, col));
        return possibleNumbers;
    }

    private Set<Integer> getPossibleNumbersForRow(int row) {
        return IntStream.of(board[row])
               .filter(i -> i!= 0)
               .boxed()
               .collect(toSet());
    }

    private Set<Integer> getPossibleNumbersForCol(int col) {
        return IntStream.range(0, board.length)
               .map(i -> board[i][col])
               .filter(i -> i!= 0)
               .boxed()
               .collect(toSet());
    }

    private Set<Integer> getPossibleNumbersForBox(int row, int col) {
        int boxRow = (row / 3) * 3;
        int boxCol = (col / 3) * 3;
        return IntStream.range(0, 3)
               .flatMap(i -> IntStream.range(0, 3)
                       .map(j -> board[boxRow + i][boxCol + j])
                       .filter(i1 -> i1!= 0)
                       .boxed())
               .collect(toSet());
    }

    public boolean isSolved() {
        return Arrays.stream(board)
               .allMatch(row -> Arrays.stream(row)
                       .allMatch(i -> i!= 0));
