public class CodeAssistant {

	private static final String URL_BASE = "http://localhost:8080/codeassistant/api/v1/codeassistant";

	public static String generateCode(String language, String code) throws CodeAssistantException {
		String url = URL_BASE + "?language=" + language + "&code=" + code;
		try {
			URL obj = new URL(url);
			URLConnection conn = obj.openConnection();
			BufferedReader in = new BufferedReader(new InputStreamReader(conn.getInputStream()));
			String inputLine;
			StringBuffer response = new StringBuffer();
			while ((inputLine = in.readLine())!= null) {
				response.append(inputLine);
			}
			in.close();
			return response.toString();
		} catch (IOException e) {
			throw new CodeAssistantException(e);
		}
	}

