package ru.kostia.generator;

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Generator {
    private static final String ASSISTANT_START = "<|assistant|>";
    private static final String SYSTEM_START = "<|system|>";
    private static final String USER_START = "<|user|>";

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.println("Enter the code you want to generate:");
        String code = scanner.nextLine();
        System.out.println("Generated code:");
        System.out.println(generateCode(code));
    }

    private static String generateCode(String code) {
        List<String> lines = new ArrayList<>();
        String[] codeLines = code.split("\n");
        for (String line : codeLines) {
            String[] parts = line.split("\\|");
            if (parts.length == 2) {
                if (parts[0].equals(ASSISTANT_START)) {
                    lines.add(parts[1]);
                } else if (parts[0].equals(SYSTEM_START)) {
                    lines.add("System.out.println(\"" + parts[1] + "\");");
                } else if (parts[0].equals(USER_START)) {
                    lines.add(parts[1]);
                }
            } else {
                lines.add(line);
            }
        }
        return String.join("\n", lines);
    }
}

}
