public class TwoToOne {
	public static String longest(String s1, String s2) {
		Set<Character> set = new HashSet<>();
		for (char c : s1.toCharArray()) {
			set.add(c);
		}
		for (char c : s2.toCharArray()) {
			set.add(c);
		}
		StringBuilder sb = new StringBuilder();
		for (char c : set) {
			sb.append(c);
		}
		return sb.toString();
	}
}
