import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.stream.Collectors;

import com.github.h0tk3y.java.test.model.Question;

public class Test {
    private static final String QUESTIONS_PATH = "src/main/resources/questions.json";

    public static void main(String[] args) {
        List<Question> questions = loadQuestions();
        Question question = questions.get(0);
        System.out.println(question.getQuestion());
    }

    private static List<Question> loadQuestions() {
        try {
            Path path = Paths.get(QUESTIONS_PATH);
            String json = new String(Files.readAllBytes(path));
            return Arrays.stream(json.split("\n"))
                   .map(Question::new)
                   .collect(Collectors.toList());
        } catch (IOException e) {
            e.printStackTrace();
        }
        return Collections.emptyList();
    }
}
