/**
 * Bài 1: Viết chương trình nhập vào 2 số nguyên dương a và b.
 * Tính tổng, hiệu, tích và thương của 2 số nguyên đó.
 * 
 * Input
 * 	Nhập vào 2 số nguyên dương a và b (a, b ≤ 100)
 * 
 * Output
 * 	In ra kết quả các phép tính trên 2 số nguyên đó
 */
public class Lab02_01 {
	public static void main(String[] args) {
		Scanner scanner = new Scanner(System.in);

		System.out.print("Nhap vao so a: ");
		int a = scanner.nextInt();

		System.out.print("Nhap vao so b: ");
		int b = scanner.nextInt();

		System.out.println("Tong cua 2 so nguyen la: " + (a + b));
		System.out.println("Hieu cua 2 so nguyen la: " + (a - b));
		System.out.println("Tich cua 2 so nguyen la: " + (a * b));
		System.out.println("Thuong cua 2 so nguyen la: " + (a / b));

		scanner.close();
	}
}
