package com.github.misterbeast.java.explainer.model;

import java.util.List;

public class Code {
    private String code;
    private List<String> comments;
    private List<String> tokens;
    private List<String> keywords;
    private List<String> operators;
    private List<String> literals;
    private List<String> userComments;

    public Code() {
    }

    public Code(String code, List<String> comments, List<String> tokens, List<String> keywords, List<String> operators, List<String> literals, List<String> userComments) {
        this.code = code;
        this.comments = comments;
        this.tokens = tokens;
        this.keywords = keywords;
        this.operators = operators;
        this.literals = literals;
        this.userComments = userComments;
    }

    public String getCode() {
        return code;
    }

    public void setCode(String code) {
        this.code = code;
    }

    public List<String> getComments() {
        return comments;
    }

    public void setComments(List<String> comments) {
        this.comments = comments;
    }

    public List<String> getTokens() {
        return tokens;
    }

    public void setTokens(List<String> tokens) {
        this.tokens = tokens;
    }

    public List<String> getKeywords() {
        return keywords;
    }

    public void setKeywords(List<String> keywords) {
        this.keywords = keywords;
    }

    public List<String> getOperators() {
        return operators;
    }

    public void setOperators(List<String> operators) {
        this.operators = operators;
    }

    public List<String> getLiterals() {
        return literals;
    }

    public void setLiterals(List<String> literals) {
        this.literals = literals;
    }

    public List<String> getUserComments() {
        return userComments;
    }

    public void setUserComments(List<String> userComments) {
        this.userComments = userComments;
    }
}
