import java.util.ArrayList;
import java.util.List;

/**
 * @author  ()
 * @since 2016-07-20
 */
public class FindTheDivisors {
    public static List<Integer> divisors(int n) {
        List<Integer> divisors = new ArrayList<Integer>();
        for (int i = 1; i <= n; i++) {
            if (n % i == 0) {
                divisors.add(i);
            }
        }
        return divisors;
    }
}
