package com.github.michaelbull.javafx.challenge.model;

import java.util.ArrayList;
import java.util.List;

import com.github.michaelbull.javafx.challenge.model.challenge.Challenge;
import com.github.michaelbull.javafx.challenge.model.challenge.ChallengeCategory;
import com.github.michaelbull.javafx.challenge.model.challenge.ChallengeType;

import javafx.beans.property.SimpleStringProperty;
import javafx.beans.property.StringProperty;

public class User {
    private StringProperty name = new SimpleStringProperty();
    private StringProperty email = new SimpleStringProperty();
    private StringProperty password = new SimpleStringProperty();
    private List<Challenge> challenges = new ArrayList<Challenge>();

    public User(String name, String email, String password) {
        this.name.set(name);
        this.email.set(email);
        this.password.set(password);
    }

    public String getName() {
        return name.get();
    }

    public void setName(String name) {
        this.name.set(name);
    }

    public StringProperty nameProperty() {
        return name;
    }

    public String getEmail() {
        return email.get();
    }

    public void setEmail(String email) {
        this.email.set(email);
    }

    public StringProperty emailProperty() {
        return email;
    }

    public String getPassword() {
        return password.get();
    }

    public void setPassword(String password) {
        this.password.set(password);
    }

    public StringProperty passwordProperty() {
        return password;
    }

    public List<Challenge> getChallenges() {
        return challenges;
    }

    public void setChallenges(List<Challenge> challenges) {
        this.challenges = challenges;
    }

    public void addChallenge(Challenge challenge) {
        this.challenges.add(challenge);
    }

    public void addChallenge(ChallengeCategory category, ChallengeType type) {
        Challenge challenge = new Challenge(category, type);
        this.challenges.add(challenge);
    }
}
