package org.seckill.controller;

import org.seckill.entity.Login;
import org.seckill.service.LoginService;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestMethod;
import org.springframework.web.bind.annotation.ResponseBody;

@Controller
@RequestMapping("/login")
public class LoginController {

	@Autowired
	private LoginService loginService;

	@RequestMapping(value="/login",method=RequestMethod.POST)
	public String login(Login login,Model model){
		model.addAttribute("login", loginService.login(login));
		return "index";
	}

	@RequestMapping(value="/register",method=RequestMethod.POST)
	public String register(Login login,Model model){
		model.addAttribute("login", loginService.register(login));
		return "index";
	}

	@RequestMapping(value="/logout",method=RequestMethod.GET)
	public String logout(Model model){
		model.addAttribute("login", null);
		return "index";
	}

	@RequestMapping(value="/checkLogin",method=RequestMethod.GET)
	@ResponseBody
	public Login checkLogin(Login login){
		return loginService.checkLogin(login);
	}

}
