package com.github.krukale.expertprogrammer;

import java.util.Objects;

public class Problem {

    private final String title;
    private final String description;
    private final String code;

    public Problem(String title, String description, String code) {
        this.title = title;
        this.description = description;
        this.code = code;
    }

    public String getTitle() {
        return title;
    }

    public String getDescription() {
        return description;
    }

    public String getCode() {
        return code;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass()!= o.getClass()) return false;
        Problem problem = (Problem) o;
        return Objects.equals(title, problem.title) &&
                Objects.equals(description, problem.description) &&
                Objects.equals(code, problem.code);
    }

    @Override
    public int hashCode() {
        return Objects.hash(title, description, code);
    }

    @Override
    public String toString() {
        return "Problem{" +
                "title='" + title + '\'' +
                ", description='" + description + '\'' +
                ", code='" + code + '\'' +
                '}';
    }
}
