package nl.hu.toe.wiskunde;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Scanner;

public class Wiskunde {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.println("Wat wil je berekenen?");
        String input = scanner.nextLine();
        String[] split = input.split(" ");
        String[] operators = {"+", "-", "*", "/"};
        List<String> operatorList = new ArrayList<>(Arrays.asList(operators));
        if (operatorList.contains(split[1])) {
            switch (split[1]) {
                case "+":
                    System.out.println(Integer.parseInt(split[0]) + Integer.parseInt(split[2]));
                    break;
                case "-":
                    System.out.println(Integer.parseInt(split[0]) - Integer.parseInt(split[2]));
                    break;
                case "*":
                    System.out.println(Integer.parseInt(split[0]) * Integer.parseInt(split[2]));
                    break;
                case "/":
                    System.out.println(Integer.parseInt(split[0]) / Integer.parseInt(split[2]));
                    break;
                default:
                    System.out.println("Ongeldige operator");
                    break;
            }
        } else {
            System.out.println("Ongeldige operator");
        }
    }
}
