package com.naga.exercises.easy;

import java.util.HashMap;
import java.util.Map;

/**
 * Given a string, count the number of characters (i.e. unique characters) in it.
 *
 * @author 
 */
public class CountingCharacters {

    public static void main(String[] args) {
        System.out.println(countCharacters(""));
        System.out.println(countCharacters("abcde"));
        System.out.println(countCharacters("abcdeaa"));
        System.out.println(countCharacters("abcdeaaab"));
    }

    public static int countCharacters(String s) {
        Map<Character, Integer> charCount = new HashMap<>();
        for (char c : s.toCharArray()) {
            if (charCount.containsKey(c)) {
                charCount.put(c, charCount.get(c) + 1);
            } else {
                charCount.put(c, 1);
            }
        }
        return charCount.size();
    }
}
