	public void act(ConcurrentHashMap<Integer, Action<SendToRepairPrivateActionState>> privateActions) {
		if (state.getPrivateAction().getState() == SendToRepairPrivateActionState.FINISHED) {
			state.getPrivateAction().act(privateActions);
		} else {
			state.getPrivateAction().act(privateActions);
		}
	}

	@Override
	public SendToRepairPrivateActionState finish() {
		return state.getPrivateAction().finish();
	}

	@Override
	public SendToRepairPrivateActionState build() {
		SendToRepairPrivateActionBuilder builder = new SendToRepairPrivateActionBuilder();
		builder.setSendToRepairPrivateAction(state.getPrivateAction());
		return builder.build();
