package fr.umlv.math;

import java.util.Scanner;

public class Math {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        System.out.println("Entrez une expression mathématique:");
        String expression = sc.nextLine();

        try {
            System.out.println(expression + " = " + evaluate(expression));
        } catch (Exception e) {
            System.out.println(e.getMessage());
        }
    }

    public static double evaluate(String expression) throws Exception {
        if (expression.contains("+")) {
            return evaluate(expression.split("\\+")[0]) + evaluate(expression.split("\\+")[1]);
        }
        if (expression.contains("-")) {
            return evaluate(expression.split("-")[0]) - evaluate(expression.split("-")[1]);
        }
        if (expression.contains("*")) {
            return evaluate(expression.split("\\*")[0]) * evaluate(expression.split("\\*")[1]);
        }
        if (expression.contains("/")) {
            return evaluate(expression.split("/")[0]) / evaluate(expression.split("/")[1]);
        }
        if (expression.contains("^")) {
            return Math.pow(evaluate(expression.split("\\^")[0]), evaluate(expression.split("\\^")[1]));
        }
        if (expression.contains("sin")) {
            return Math.sin(evaluate(expression.split("sin")[1]));
        }
        if (expression.contains("cos")) {
            return Math.cos(evaluate(expression.split("cos")[1]));
        }
        if (expression.contains("tan")) {
            return Math.tan(evaluate(expression.split("tan")[1]));
        }
        if (expression.contains("log")) {
            return Math.log(evaluate(expression.split("log")[1]));
        }
        if (expression.contains("sqrt")) {
            return Math.sqrt(evaluate(expression.split("sqrt")[1]));
        }
        return Double.parseDouble(expression);
    }
}
