package ru.mail.park.tutor;

import ru.mail.park.tutor.model.TutorModel;
import ru.mail.park.tutor.model.User;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;

public class Tutor {

    private TutorModel tutorModel;

    private List<User> users;

    private AtomicInteger userCounter;

    public Tutor(TutorModel tutorModel) {
        this.tutorModel = tutorModel;
        this.users = new ArrayList<>();
        this.userCounter = new AtomicInteger();
    }

    public void addUser(User user) {
        users.add(user);
    }

    public void addUser(String name, String surname, String login, String password) {
        users.add(new User(name, surname, login, password, userCounter.getAndIncrement()));
    }

    public User getUser(int id) {
        return users.get(id);
    }

    public List<User> getUsers() {
        return users;
    }

    public void setUsers(List<User> users) {
        this.users = users;
    }

    public TutorModel getTutorModel() {
        return tutorModel;
    }

    public void setTutorModel(TutorModel tutorModel) {
        this.tutorModel = tutorModel;
    }
}
