import java.util.List;

public class MemberValuePair extends Node {
    private final Name name;
    private final Expression value;

    public MemberValuePair(Name name, Expression value) {
        this.name = name;
        this.value = value;
    }

    public MemberValuePair(Name name, Expression value, List<Comment> comments) {
        super(comments);
        this.name = name;
        this.value = value;
    }

    public MemberValuePair(Name name, Expression value, List<Comment> comments, List<Statement> statements) {
        super(comments, statements);
        this.name = name;
        this.value = value;
    }

    public MemberValuePair(Name name, Expression value, List<Comment> comments, List<Statement> statements, List<Type> thrownExceptions) {
        super(comments, statements, thrownExceptions);
        this.name = name;
        this.value = value;
    }

    public Name getName() {
        return name;
    }

    public Expression getValue() {
        return value;
    }

    @Override
    public String toString() {
        return name + ": " + value;
    }
}
