        cin >> a[i];
    }
    int k;
    cin >> k;
    int l = 0;
    int r = 0;
    int min_l = 0;
    int min_r = 0;
    int min_sum = 0;
    int sum = 0;
    while (r < n) {
        while (sum < k && r < n) {
            sum += a[r];
            r++;
        }
        while (sum >= k && l < n) {
            if (sum - a[l] < k) {
                sum -= a[l];
                l++;
            } else {
                if (min_sum == 0 || sum < min_sum) {
                    min_sum = sum;
                    min_l = l;
                    min_r = r;
                }
                sum -= a[l];
                l++;
            }
        }
    }
    cout << min_l << " " << min_r << endl;
    return 0;
}
