class Solution:
    def deleteMiddle(self, head: ListNode) -> ListNode:
        if not head:
            return None
        if not head.next:
            return None
        slow, fast = head, head.next
        while fast and fast.next:
            slow, fast = slow.next, fast.next.next
        slow.next = slow.next.next
        return head
