package com.github.jankroken.trivia;

import java.io.IOException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Random;

import com.github.jankroken.trivia.model.Question;
import com.github.jankroken.trivia.model.TriviaOptions;

public class Trivia {

    private final List<Question> questions;
    private final List<Question> answers;
    private final Random random;

    public Trivia(List<Question> questions) {
        this.questions = questions;
        this.answers = new ArrayList<>();
        this.random = new Random();
    }

    public void addAnswer(Question answer) {
        answers.add(answer);
    }

    public TriviaOptions getOptions() {
        Question question = getQuestion();
        List<Question> answers = getAnswers();

        return new TriviaOptions(question, answers);
    }

    private Question getQuestion() {
        int index = random.nextInt(questions.size());
        return questions.get(index);
    }

    private List<Question> getAnswers() {
        List<Question> answers = new ArrayList<>();

        while (answers.size() < 3) {
            Question answer = getQuestion();

            if (!answers.contains(answer)) {
                answers.add(answer);
            }
        }

        Collections.shuffle(answers);
        answers.add(0, getQuestion());

        return answers;
    }

    public void shuffleAnswers() {
        Collections.shuffle(answers);
    }
}
