import com.github.javaparser.ast.visitor.Visitable;
import com.github.javaparser.ast.visitor.VoidVisitorAdapter;

public class CharLiteralExpr extends LiteralExpr implements Visitable {
    private char value;

    public CharLiteralExpr(char value) {
        this.value = value;
    }

    public CharLiteralExpr(char value, NodeList<MarkerAnnotationExpr> markerAnnotations, NodeList<MemberValuePair> memberValuePairs, NodeList<PairExpression> pairs) {
        super(markerAnnotations, memberValuePairs, pairs);
        this.value = value;
    }

    public char getValue() {
        return value;
    }

    public void setValue(char value) {
        this.value = value;
    }

    @Override
    public <R, A> R accept(VoidVisitor<R, A> v, A arg) {
        return v.visit(this, arg);
    }

    @Override
    public String toString() {
        return "'" + value + "'";
    }
}
