package com.github.kayzer.exercism.java.pangram;

import java.util.HashSet;
import java.util.Set;
import java.util.regex.Pattern;
import java.util.stream.Collectors;
import java.util.stream.Stream;

public class Pangram {
    private final String sentence;

    public Pangram(String sentence) {
        this.sentence = sentence;
    }

    public boolean isPangram() {
        final Set<Character> alphabet = Stream.of("abcdefghijklmnopqrstuvwxyz").map(Character::valueOf).collect(Collectors.toSet());
        final Set<Character> sentenceLetters = Stream.of(sentence.toLowerCase().replaceAll("[^a-z]", ""))
               .map(String::toCharArray)
               .flatMap(Stream::of)
               .collect(Collectors.toSet());
        return sentenceLetters.containsAll(alphabet);
    }
}
