package nl.knaw.huc.c10.c10_06;

public static boolean verifyJWT(String jwt, Map<String, String> validAlgorithms) {
    String[] parts = jwt.split("\\.");
    if (parts.length!= 3) {
        return false;
    }

    String header = parts[0];
    String payload = parts[1];
    String signature = parts[2];

    // Decode the header
    String decodedHeader = new String(Base64.getUrlDecoder().decode(header));
    Map<String, String> headerMap = new HashMap<>();
    for (String pair : decodedHeader.split(",")) {
        String[] kv = pair.split("=");
        headerMap.put(kv[0], kv[1]);
    }

    // Decode the payload
    String decodedPayload = new String(Base64.getUrlDecoder().decode(payload));
    Map<String, String> payloadMap = new HashMap<>();
    for (String pair : decodedPayload.split(",")) {
        String[] kv = pair.split("=");
        payloadMap.put(kv[0], kv[1]);
    }

    // Decode the signature
    String decodedSignature = new String(Base64.getUrlDecoder().decode(signature));

    // Check which algorithm is used
    String algorithm = headerMap.get("alg");
    if (algorithm == null) {
        return false;
    } else if (!validAlgorithms.containsKey(algorithm)) {
        return false;
    }

    // Check if the signature is valid
    String expectedSignature = validAlgorithms.get(algorithm);
    if (!expectedSignature.equals(decodedSignature)) {
        return false;
    }

    // Check if the payload is valid
    if (payloadMap.get("exp") == null || Long.parseLong(payloadMap.get("exp")) < System.currentTimeMillis() / 1000) {
        return false;
    }

    if (payloadMap.get("iat") == null || Long.parseLong(payloadMap.get("iat")) > System.currentTimeMillis() / 1000) {
        return false;
    }

    return true;
}
}

