public static boolean verifyToken(String token) {
    // Décode le jeton
    String[] parts = token.split("\\.");
    if (parts.length!= 3) {
        return false;
    }
    String header = new String(Base64.getDecoder().decode(parts[0]));
    String payload = new String(Base64.getDecoder().decode(parts[1]));
    String signature = new String(Base64.getDecoder().decode(parts[2]));

    // Vérifie la signature du jeton
    Map<String, String> headerMap = new HashMap<>();
    for (String headerPart : header.split(",")) {
        headerMap.put(headerPart.split("=")[0], headerPart.split("=")[1]);
    }
    String algorithm = headerMap.get("alg");
    String key = headerMap.get("kid");
    if (algorithm.equals("none")) {
        return false;
    } else if (algorithm.equals("HS256")) {
        // Vérifie la signature avec la clé de la clé publique
        String expectedSignature = Base64.getEncoder().encodeToString(
            new HS256().sign(payload.getBytes(), key.getBytes()));
        return expectedSignature.equals(signature);
    } else {
        return false;
    }
}
