package com.github.jlangch.venus.impl.ast.nodes;

import java.util.Collections;
import java.util.List;
import java.util.Map;

public class AstNodeVisitorContext {

    public static final AstNodeVisitorContext EMPTY = new AstNodeVisitorContext();

    private final Map<String, Object> attributes;

    public AstNodeVisitorContext() {
        this(Collections.emptyMap());
    }

    public AstNodeVisitorContext(Map<String, Object> attributes) {
        this.attributes = attributes;
    }

    public Object getAttribute(String name) {
        return attributes.get(name);
    }

    public void setAttribute(String name, Object value) {
        attributes.put(name, value);
    }

    public void setAttributes(Map<String, Object> attributes) {
        this.attributes.putAll(attributes);
    }

    public List<String> getAttributeNames() {
        return List.copyOf(attributes.keySet());
    }

    public static class VisitResult {
        private final boolean stop;
        private final Object result;

        public VisitResult(boolean stop) {
            this(stop, null);
        }

        public VisitResult(boolean stop, Object result) {
            this.stop = stop;
            this.result = result;
        }

        public boolean stop() {
            return stop;
        }

        public Object result() {
            return result;
        }
    }
}

