package com.github.victorgarciaesgi.java.exercises.exercism.java.exercises.practice.twelve_days;

import java.util.ArrayList;
import java.util.List;

public class TwelveDays {
    public static final String[] DAYS = { "first", "second", "third", "fourth", "fifth", "sixth", "seventh", "eighth", "ninth", "tenth", "eleventh", "twelfth" };

    public static final String[] GIFTS = { "a Partridge in a Pear Tree", "Two Turtle Doves", "Three French Hens", "Four Calling Birds", "Five Gold Rings", "Six Geese-a-Laying", "Seven Swans-a-Swimming", "Eight Maids-a-Milking", "Nine Ladies Dancing", "Ten Lords-a-Leaping", "Eleven Pipers Piping", "Twelve Drummers Drumming" };

    public static String sing() {
        List<String> verses = new ArrayList<>();
        for (int i = 0; i < 12; i++) {
            verses.add(verse(i + 1));
        }

        return verses.stream().reduce("", (s, s1) -> s + s1 + "\n");
    }

    private static String verse(int day) {
        String verse = "On the " + DAYS[day - 1] + " day of Christmas my true love gave to me: ";
        for (int i = day; i > 0; i--) {
            verse += GIFTS[i - 1] + ", ";
        }
        return verse.substring(0, verse.length() - 2) + ".";
    }
}
