import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.util.ArrayList;
import java.util.List;

import it.polito.tdp.parole.model.Parola;

public class ParoleDAO {

	public List<Parola> listParole(String parola) {
		String sql = "SELECT * FROM parole WHERE parola =?";
		List<Parola> parole = new ArrayList<>();

		try {
			Connection conn = DBConnect.getConnection();
			PreparedStatement st = conn.prepareStatement(sql);
			st.setString(1, parola);
			ResultSet res = st.executeQuery();
			while (res.next()) {
				Parola p = new Parola(res.getString("parola"), res.getInt("conteggio"));
				parole.add(p);
			}
			conn.close();
			return parole;
		} catch (SQLException e) {
			e.printStackTrace();
			return null;
		}
	}

}
