import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

import org.jgrapht.Graph;
import org.jgrapht.Graphs;
import org.jgrapht.graph.DefaultWeightedEdge;

import it.polito.tdp.borders.db.BordersDAO;

public class Model {

	private BordersDAO dao;
	private Map<Integer, Country> countryMap;
	private Map<Integer, Border> borderMap;
	private Graph<Country, DefaultWeightedEdge> grafo;

	public Model() {
		this.dao = new BordersDAO();
		this.countryMap = new HashMap<>();
		this.borderMap = new HashMap<>();
		this.grafo = new WeightedGraph<>();
	}

	public void creaGrafo(int anno) {
		this.countryMap = dao.loadAllCountries();
		this.borderMap = dao.loadAllBorders(anno);

		for(Border b : this.borderMap.values()) {
			if(!this.countryMap.containsKey(b.getCountry1())) {
				this.countryMap.put(b.getCountry1(), new Country(b.getCountry1()));
			}
			if(!this.countryMap.containsKey(b.getCountry2())) {
				this.countryMap.put(b.getCountry2(), new Country(b.getCountry2()));
			}
		}

		this.grafo.addVertexes(this.countryMap.values());
		this.grafo.addEdges(this.borderMap.values());
	}

	public List<Country> getCountryList() {
		return new ArrayList<>(this.countryMap.values());
	}

	public List<Border> getBorderList() {
		return new ArrayList<>(this.borderMap.values());
	}

	public Graph<Country, DefaultWeightedEdge> getGrafo() {
		return this.grafo;
	}
}

