package ir.ac.kntu.programming.controller;

import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;

import ir.ac.kntu.programming.model.Test;
import ir.ac.kntu.programming.model.User;
import ir.ac.kntu.programming.service.TestService;
import ir.ac.kntu.programming.service.UserService;

@Controller
@RequestMapping("/test")
public class TestController {

	private final TestService testService;
	private final UserService userService;

	public TestController(TestService testService, UserService userService) {
		this.testService = testService;
		this.userService = userService;
	}

	@GetMapping("/{id}")
	public String getTest(@PathVariable("id") Long id, Model model) {
		Test test = testService.getTest(id);
		model.addAttribute("test", test);
		return "test";
	}

	@PostMapping("/{id}")
	public String postTest(@PathVariable("id") Long id, @RequestParam("answer") String answer, Model model) {
		Test test = testService.getTest(id);
		User user = userService.getUser();
		if (test.getAnswer().equals(answer)) {
			user.addPoint(test.getPoint());
		}
		userService.save(user);
		model.addAttribute("test", test);
		return "test";
	}

}
