package com.github.ricky12345.codewars.solutions.kyu8;

import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;

/**
 * <a href="https://www.codewars.com/kata/valid-parentheses">Valid Parentheses</a>
 *
 * @author 
 */
public class ValidParentheses {
    public static boolean validParentheses(String input) {
        Map<Character, Character> map = new HashMap<>();
        map.put(')', '(');
        map.put('}', '{');
        map.put(']', '[');

        char[] chars = input.toCharArray();
        Arrays.sort(chars);

        int i = 0;
        while (i < chars.length) {
            char c = chars[i];
            if (c == '(' || c == '{' || c == '[') {
                i++;
            } else if (i + 1 < chars.length) {
                char c2 = chars[i + 1];
                if (map.get(c2) == c) {
                    i += 2;
                } else {
                    return false;
                }
            } else {
                return false;
            }
        }

        return true;
    }
}
