import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;
import java.io.Serializable;
import java.util.Base64;

import com.github.michaelwittig.recruitment.challenge.model.ChallengeData;
import com.github.michaelwittig.recruitment.challenge.model.ChallengeResult;

public class Challenge implements Serializable {
    private static final long serialVersionUID = 1L;

    private ChallengeData data;
    private ChallengeResult result;

    public Challenge(ChallengeData data) {
        this.data = data;
    }

    public void solve() {
        try {
            ByteArrayOutputStream baos = new ByteArrayOutputStream();
            ObjectOutputStream oos = new ObjectOutputStream(baos);
            oos.writeObject(this.data);
            oos.close();
            byte[] bytes = baos.toByteArray();
            String encoded = Base64.getEncoder().encodeToString(bytes);
            this.result = new ChallengeResult(encoded);
        } catch (IOException e) {
            this.result = new ChallengeResult(e);
        }
    }

    public ChallengeResult getResult() {
        return result;
    }
}
