package com.github.kislyuk.codewars.kyu7;

import java.util.ArrayList;
import java.util.List;
import java.util.stream.IntStream;

/**
 * You are given an array of integers. On each move you are allowed to increase exactly one of its element by one. Find
 * the minimal number of moves required to obtain a strictly increasing sequence from the input.
 * 
 * Example
 * For inputArray = [1, 1, 1], the output should be 3.
 * 
 * Input/Output
 * [input] integer array inputArray
 * 
 * Guaranteed constraints: 3 ≤ inputArray.length ≤ 10, 1 ≤ inputArray[i] ≤ 10.
 * 
 * [output] an integer
 * 
 * The minimal number of moves required to obtain a strictly increasing sequence from inputArray.
 * 
 * [Java] [C#] [PHP] [Python] [Ruby] [Rust] [Scala]
 */
public class SimpleFun33 {
    public int arrayChange(int[] inputArray) {
        int count = 0;
        List<Integer> list = new ArrayList<>();
        IntStream.of(inputArray).forEach(i -> list.add(i));
        for (int i = 0; i < list.size() - 1; i++) {
            if (list.get(i) >= list.get(i + 1)) {
                count += list.get(i) - list.get(i + 1) + 1;
                list.set(i + 1, list.get(i) + 1);
            }
        }
        return count;
    }
}
