package org.codetome.qti.util;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

import org.codetome.qti.model.AssessmentItem;

public class QtiUtil {
	public static String getQtiVersion(String qti) {
		Pattern p = Pattern.compile("<\?xml version=\"1.0\" encoding=\"UTF-8\" \?>");
		Matcher m = p.matcher(qti);
		if (m.find()) {
			return m.group(0).split(" ")[1].split("\"")[1];
		}
		return null;
	}

	public static String getAssessmentItem(String qti) {
		Pattern p = Pattern.compile("<assessmentItem([^>]+)>(.+)</assessmentItem>");
		Matcher m = p.matcher(qti);
		if (m.find()) {
			return m.group(2);
		}
		return null;
	}

	public static String getAssessmentItem(AssessmentItem assessmentItem) {
		return getAssessmentItem(assessmentItem.toXML());
	}

	public static String getAssessmentItem(String assessmentItem) {
		return getAssessmentItem(assessmentItem);
	}

	public static String getAssessmentItem(AssessmentItem assessmentItem, String version) {
		return getAssessmentItem(assessmentItem.toXML(version));
	}

	public static String getAssessmentItem(String assessmentItem, String version) {
		return getAssessmentItem(assessmentItem, version);
	}
}
