package com.github.code2040.challenge;

import org.yaml.snakeyaml.Yaml;
import org.yaml.snakeyaml.constructor.Constructor;

import java.io.IOException;
import java.net.HttpURLConnection;
import java.net.URL;
import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.Map;

public class ReverseString {
    public static void main(String[] args) throws IOException {
        HttpURLConnection connection = (HttpURLConnection) new URL("http://challenge.code2040.org/api/reverse").openConnection();
        connection.setRequestMethod("POST");
        connection.setRequestProperty("Content-Type", "application/json");
        connection.setDoOutput(true);

        Yaml yaml = new Yaml(new Constructor(HashMap.class));
        Map<String, String> request = yaml.load(new String(connection.getInputStream().readAllBytes(), StandardCharsets.UTF_8));

        StringBuilder sb = new StringBuilder(request.get("string"));
        sb.reverse();

        Map<String, String> response = new HashMap<>();
        response.put("string", sb.toString());

        String json = yaml.dump(response);
        connection.getOutputStream().write(json.getBytes(StandardCharsets.UTF_8));
        connection.getOutputStream().flush();

        System.out.println(new String(connection.getInputStream().readAllBytes(), StandardCharsets.UTF_8));
    }
}
