import javax.swing.filechooser.FileNameExtensionFilter;

import ee.ut.math.tvt.java.ui.JavaEditor;

public class LoadAction extends AbstractAction implements ActionListener {
	private static final long serialVersionUID = 1L;
	private JavaEditor editor;

	public LoadAction(JavaEditor editor) {
		this.editor = editor;
		putValue(NAME, "Load");
	}

	@Override
	public void actionPerformed(ActionEvent e) {
		JFileChooser fc = new JFileChooser();
		FileNameExtensionFilter filter = new FileNameExtensionFilter("Java Files", "java");
		fc.setFileFilter(filter);
		int returnVal = fc.showOpenDialog(editor);
		if (returnVal == JFileChooser.APPROVE_OPTION) {
			File file = fc.getSelectedFile();
			try {
				editor.load(file);
			} catch (IOException e1) {
				JOptionPane.showMessageDialog(editor, "File could not be loaded.");
			}
		}
	}
}
