public class TestJavaParser {

    @Test
    public void testSimple() {
        CompilationUnit compilationUnit = JavaParser.parse("public class Foo { public void bar() { System.out.println(\"Hello\"); } }");
        ClassOrInterfaceDeclaration classDeclaration = compilationUnit.getTypes().get(0);
        MethodDeclaration methodDeclaration = classDeclaration.getMethods().get(0);
        BlockStmt blockStmt = methodDeclaration.getBody();
        assertEquals(1, blockStmt.getStatements().size());
        ExpressionStmt expressionStmt = (ExpressionStmt) blockStmt.getStatements().get(0);
        MethodCallExpr methodCallExpr = (MethodCallExpr) expressionStmt.getExpression();
        NameExpr nameExpr = (NameExpr) methodCallExpr.getScope();
        assertEquals("System", nameExpr.getName());
        assertEquals("out", methodCallExpr.getMethodName());
        assertEquals(1, methodCallExpr.getArguments().size());
        assertEquals("Hello", methodCallExpr.getArguments().get(0).toString());
    }

