package com.github.saphyra.apphub.service.impl.util;

import java.time.Duration;
import java.time.LocalDateTime;
import java.time.temporal.ChronoUnit;

public class TimeUtil {
    private static final int SECONDS_IN_MINUTE = 60;
    private static final int SECONDS_IN_HOUR = 60 * SECONDS_IN_MINUTE;
    private static final int SECONDS_IN_DAY = 24 * SECONDS_IN_HOUR;

    private TimeUtil() {
    }

    public static int getDifferenceInSeconds(LocalDateTime start, LocalDateTime end) {
        return (int) Duration.between(start, end).toSeconds();
    }

    public static int getDifferenceInMinutes(LocalDateTime start, LocalDateTime end) {
        return (int) Duration.between(start, end).toMinutes();
    }

    public static int getDifferenceInHours(LocalDateTime start, LocalDateTime end) {
        return (int) Duration.between(start, end).toHours();
    }

    public static int getDifferenceInDays(LocalDateTime start, LocalDateTime end) {
        return (int) Duration.between(start, end).toDays();
    }

    public static int getDifferenceInWeeks(LocalDateTime start, LocalDateTime end) {
        return (int) Duration.between(start, end).to(ChronoUnit.WEEKS);
    }

    public static int getDifferenceInMonths(LocalDateTime start, LocalDateTime end) {
        return (int) Duration.between(start, end).to(ChronoUnit.MONTHS);
    }

    public static int getDifferenceInYears(LocalDateTime start, LocalDateTime end) {
        return (int) Duration.between(start, end).to(ChronoUnit.YEARS);
    }
}
