package ru.spbau.mit.servlets;

import ru.spbau.mit.servlets.Servlets.ServletType;

import javax.servlet.ServletException;
import javax.servlet.http.HttpServlet;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import java.io.IOException;
import java.io.PrintWriter;
import java.util.HashMap;
import java.util.Map;

public class Servlet extends HttpServlet {
    private static final Map<String, ServletType> servletTypes = new HashMap<>();

    static {
        servletTypes.put("/servlet", ServletType.CLASS_X);
        servletTypes.put("/servlet/class-x", ServletType.CLASS_X);
        servletTypes.put("/servlet/class-y", ServletType.CLASS_Y);
        servletTypes.put("/servlet/class-z", ServletType.CLASS_Z);
        servletTypes.put("/servlet/class-a", ServletType.CLASS_A);
        servletTypes.put("/servlet/class-b", ServletType.CLASS_B);
        servletTypes.put("/servlet/class-c", ServletType.CLASS_C);
        servletTypes.put("/servlet/class-d", ServletType.CLASS_D);
        servletTypes.put("/servlet/class-e", ServletType.CLASS_E);
        servletTypes.put("/servlet/class-f", ServletType.CLASS_F);
        servletTypes.put("/servlet/class-g", ServletType.CLASS_G);
        servletTypes.put("/servlet/class-h", ServletType.CLASS_H);
        servletTypes.put("/servlet/class-i", ServletType.CLASS_I);
        servletTypes.put("/servlet/class-j", ServletType.CLASS_J);
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) throws ServletException, IOException {
        final ServletType servletType = servletTypes.get(req.getRequestURI());
        if (servletType == null) {
            resp.sendError(HttpServletResponse.SC_NOT_FOUND);
            return;
        }

        final PrintWriter out = resp.getWriter();
        out.println(servletType.getAnswer());
    }
}

