package it.unipd.tos.business.impl;

import java.util.List;

import it.unipd.tos.business.IUserService;
import it.unipd.tos.model.User;
import it.unipd.tos.model.User.Role;
import it.unipd.tos.model.User.Status;
import it.unipd.tos.persistence.IUserDao;
import it.unipd.tos.persistence.impl.UserDao;

public class UserServiceImpl implements IUserService {

	private IUserDao userDao = new UserDao();

	@Override
	public User createUser(String username, String password, String name, String surname, String email, Role role) {
		User user = new User(username, password, name, surname, email, role, Status.ACTIVE);
		userDao.save(user);
		return user;
	}

	@Override
	public User getUser(String username) {
		return userDao.findByUsername(username);
	}

	@Override
	public List<User> getUsers() {
		return userDao.findAll();
	}

	@Override
	public User updateUser(String username, String name, String surname, String email, Role role, Status status) {
		User user = userDao.findByUsername(username);
		user.setName(name);
		user.setSurname(surname);
		user.setEmail(email);
		user.setRole(role);
		user.setStatus(status);
		userDao.save(user);
		return user;
	}

	@Override
	public void deleteUser(String username) {
		User user = userDao.findByUsername(username);
		userDao.delete(user);
	}

	@Override
	public boolean isUserPresent(String username) {
		return userDao.findByUsername(username)!= null;
	}
}
