package com.github.hcsp.io;

import java.io.File;
import java.io.FileOutputStream;
import java.io.IOException;
import java.io.OutputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class FileAccessor {
    // 题目要求你在这里实现一个FileAccessor类，它提供如下两个功能：
    // 1. 从文件中读取字符串，将其存放到一个字符串列表中并返回。如果文件不存在，则返回一个空的字符串列表。
    // 2. 将一个字符串写入到文件中，如果文件不存在则创建它。
    // 请实现以下方法
    public static List<String> readDataFromFile(String fileName) {
        List<String> list = new ArrayList<>();
        try {
            Scanner scanner = new Scanner(new File(fileName));
            while (scanner.hasNextLine()) {
                list.add(scanner.nextLine());
            }
        } catch (IOException e) {
            e.printStackTrace();
        }

        return list;
    }

    public static void writeDataToFile(String fileName, String data) {
        try {
            File file = new File(fileName);
            if (!file.exists()) {
                file.createNewFile();
            }
            OutputStream outputStream = new FileOutputStream(file, true);
            outputStream.write(data.getBytes());
            outputStream.write("\n".getBytes());
            outputStream.close();
        } catch (IOException e) {
            e.printStackTrace();
        }
