package com.github.kaylerw.codewars.katas.7kyu;

import java.util.Arrays;

public class FindTheParityOutlier {

    public static int find(int[] integers) {
        int oddCount = 0;
        int evenCount = 0;
        for (int i : integers) {
            if (i % 2 == 0) {
                evenCount++;
            } else {
                oddCount++;
            }
        }
        return oddCount == 1? Arrays.stream(integers).filter(i -> i % 2 == 1).findFirst().orElse(0) : Arrays.stream(integers).filter(i -> i % 2 == 0).findFirst().orElse(0);
    }

}
