package hu.bme.mit.train.railway;

import hu.bme.mit.train.interfaces.TrainController;
import hu.bme.mit.train.interfaces.TrainSensor;

public class Train {
    private TrainController controller;
    private TrainSensor sensor;
    private int currentStation;

    public Train(TrainController controller, TrainSensor sensor) {
        this.controller = controller;
        this.sensor = sensor;
        this.currentStation = 0;
    }

    public void move() {
        if (sensor.get(currentStation)) {
            controller.setTrainSpeed(0);
            currentStation++;
        } else {
            controller.setTrainSpeed(10);
        }
    }

    public void setController(TrainController controller) {
        this.controller = controller;
    }

    public void setSensor(TrainSensor sensor) {
        this.sensor = sensor;
    }

    public int getCurrentStation() {
        return currentStation;
