package com.github.hcsp.io;

import java.io.File;
import java.util.ArrayList;
import java.util.List;

public class FileSearch {
    /**
     * 给定一个目录，返回一个存储在该目录下所有.java扩展名的文件的列表。
     *
     * 例如，输入目录"D:\\java"，应返回.java文件"D:\\java\\a.java"，"D:\\java\\b.java"，"D:\\java\\c\\d.java"。
     *
     * <p>注意，输入目录可能不存在。
     *
     * @param directory 输入的目录
     * @return 输入目录下所有.java扩展名的文件列表
     */
    public List<File> search(String directory) {
        List<File> result = new ArrayList<>();
        File file = new File(directory);
        if (file.exists()) {
            for (File file1 : file.listFiles()) {
                if (file1.getName().endsWith(".java")) {
                    result.add(file1);
                } else if (file1.isDirectory()) {
                    result.addAll(search(file1.getPath()));
                }
            }
        }
        return result;
    }
}
