import java.util.Scanner;

/**
 * A. Next Round
 *
 * https://codeforces.com/contest/158/problem/A
 *
 * You are given a list of positive integers. You have to write a function that checks whether a given number
 * is present in the list or not.
 *
 * Input
 * The first line contains two integers n and k separated by a single space.
 * The second line contains n space-separated integers a1, a2,..., an (1 ≤ ai ≤ 100).
 *
 * Output
 * Print "YES" if the number k is present in the list and "NO" otherwise.
 *
 * Examples
 * inputCopy
 * 5 2
 * 1 3 2 2 2
 * outputCopy
 * YES
 * inputCopy
 * 5 7
 * 1 3 2 2 2
 * outputCopy
 * NO
 * Note
 * In the first example, the number 2 is present in the list.
 * In the second example, the number 7 is not present in the list.
 */
public class TaskA {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        int k = in.nextInt();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = in.nextInt();
        }

        int count = 0;
        for (int i = 0; i < n; i++) {
            if (a[i] >= a[k - 1] && a[i] > 0) {
                count++;
            }
        }

        System.out.println(count >= a[k - 1]? "YES" : "NO");
    }
}
