package fr.insalyon.dasi.xpl.ast;

import fr.insalyon.dasi.xpl.ast.visitor.ASTVisitor;
import fr.insalyon.dasi.xpl.ast.visitor.ASTVisitorException;

/**
 * Représente une affectation.
 * 
 * @author 
 */
public class Assign extends AST {
    /**
     * Le nom de la variable à affecter.
     */
    private final String varName;
    /**
     * La valeur à affecter.
     */
    private final AST value;

    /**
     * Constructeur.
     * 
     * @param varName Le nom de la variable à affecter.
     * @param value La valeur à affecter.
     */
    public Assign(String varName, AST value) {
        this.varName = varName;
        this.value = value;
    }

    /**
     * @return Le nom de la variable à affecter.
     */
    public String getVarName() {
        return varName;
    }

    /**
     * @return La valeur à affecter.
     */
    public AST getValue() {
        return value;
    }

    @Override
    public <T> T accept(ASTVisitor<T> visitor) throws ASTVisitorException {
        return visitor.visit(this);
    }
}
