            Thread thread = new Thread(() -> {
                for (int j = 0; j < 100; j++) {
                    getInstance();
                }
            });
            thread.start();
            thread.join();
        }
    }

    // 请编写多线程线程安全的单例模式实现
    public static class Single {
        private Random random = new Random();

        public int nextInt() {
            return random.nextInt();
        }
