package org.exercism.java.exercises.phone;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class PhoneNumber {
    private static final Pattern PHONE_NUMBER_PATTERN = Pattern.compile("1?\\s?\\(?\\d{3}\\)?\\s?\\d{3}\\-?\\d{4}");

    private final String number;

    public PhoneNumber(String number) {
        Matcher matcher = PHONE_NUMBER_PATTERN.matcher(number);
        if (!matcher.matches()) {
            throw new IllegalArgumentException("Invalid phone number.");
        }
        this.number = number;
    }

    public String getNumber() {
        return number;
    }

    public String getAreaCode() {
        return number.substring(1, 4);
    }

    public String getExchangeCode() {
        return number.substring(5, 8);
    }

    public String getSubscriberNumber() {
        return number.substring(9);
    }
}
