package com.github.pavlovo.ctf.service;

import com.github.pavlovo.ctf.entity.Task;
import com.github.pavlovo.ctf.entity.User;
import com.github.pavlovo.ctf.repository.TaskRepository;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

import java.util.List;
import java.util.Optional;

@Service
public class TaskService {

    private final TaskRepository taskRepository;

    @Autowired
    public TaskService(TaskRepository taskRepository) {
        this.taskRepository = taskRepository;
    }

    public List<Task> getAllTasks() {
        return taskRepository.findAll();
    }

    public Optional<Task> getTask(String name) {
        return taskRepository.findByName(name);
    }

    public Optional<Task> getTask(long id) {
        return taskRepository.findById(id);
    }

    public void save(Task task) {
        taskRepository.save(task);
    }

    public void delete(long id) {
        taskRepository.deleteById(id);
    }

    public void addTask(Task task, User user) {
        task.setAuthor(user);
        task.setSolved(0);
        task.setAttempts(0);
        taskRepository.save(task);
    }
}
