package fi.tamk.tiko.java.exam.model;

import java.util.ArrayList;
import java.util.List;

import fi.tamk.tiko.java.exam.model.questions.Question;

/**
 * Model-luokka, joka sisältää kysymyksiä.
 * 
 * @author 
 * @version 1.0
 */
public class Exam {
	/**
	 * Kysymyksiä.
	 */
	private List<Question> questions;

	/**
	 * Luo uuden kysymys-olion.
	 */
	public Exam() {
		this.questions = new ArrayList<Question>();
	}

	/**
	 * Lisää kysymys.
	 * 
	 * @param question
	 *            Kysymys, joka lisätään
	 */
	public void addQuestion(Question question) {
		this.questions.add(question);
	}

	/**
	 * Poistaa kysymys.
	 * 
	 * @param question
	 *            Kysymys, joka poistetaan
	 */
	public void removeQuestion(Question question) {
		this.questions.remove(question);
	}

	/**
	 * Palauttaa kysymysten määrän.
	 * 
	 * @return Kysymysten määrä.
	 */
	public int getQuestionCount() {
		return this.questions.size();
	}

	/**
	 * Palauttaa kysymys.
	 * 
	 * @param index
	 *            Kysymysin indeksi.
	 * @return Kysymys
	 */
	public Question getQuestion(int index) {
		return this.questions.get(index);
	}

	/**
	 * Palauttaa kysymysten listan.
	 * 
	 * @return Kysymysten listan
	 */
	public List<Question> getQuestions() {
		return this.questions;
	}
}
