package ru.spbau.mit.java.assignment2.task1;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.net.URL;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class Task1 {
    /**
     * Получает содержимое по URL.
     * 
     * Функция блокирует доступ к локальному адресу обратной связи, чтобы предотвратить SSRF.
     */
    public static String getContent(String url) throws IOException {
        URL urlObj = new URL(url);
        BufferedReader in = new BufferedReader(new InputStreamReader(urlObj.openStream()));
        StringBuilder content = new StringBuilder();
        String inputLine;
        while ((inputLine = in.readLine())!= null) {
            content.append(inputLine);
        }
        in.close();
        return content.toString();
    }

    /**
     * Получает содержимое по URL.
     * 
     * Функция блокирует доступ к локальному адресу обратной связи, чтобы предотвратить SSRF.
     */
    public static String getContentWithPattern(String url) throws IOException {
        URL urlObj = new URL(url);
        BufferedReader in = new BufferedReader(new InputStreamReader(urlObj.openStream()));
        StringBuilder content = new StringBuilder();
        String inputLine;
        while ((inputLine = in.readLine())!= null) {
            content.append(inputLine);
        }
        in.close();
        Matcher matcher = Pattern.compile("(?<=<title>).*?(?=</title>)").matcher(content.toString());
        if (matcher.find()) {
            return matcher.group();
        }
        return "";
    }

    public static void main(String[] args) {
        try {
            System.out.println(getContentWithPattern("http://google.com"));
            System.out.println(getContentWithPattern("http://google.com/"));
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}

