import nl.tudelft.securecoding.model.ast.AstNode;
import nl.tudelft.securecoding.model.ast.expressions.Expression;
import nl.tudelft.securecoding.model.ast.visitor.AstVisitor;

public class If extends Statement {

    private Expression condition;
    private Statement then;
    private Statement else_;

    public If(Expression condition, Statement then, Statement else_) {
        this.condition = condition;
        this.then = then;
        this.else_ = else_;
    }

    public Expression getCondition() {
        return condition;
    }

    public Statement getThen() {
        return then;
    }

    public Statement getElse() {
        return else_;
    }

    @Override
    public <T> T accept(AstVisitor<T> visitor) {
        return visitor.visit(this);
    }
}
